"""Capture and resolve buttons produced by a response source tool."""

from __future__ import annotations

from collections.abc import Iterator, Sequence
from contextlib import contextmanager
from contextvars import ContextVar
from typing import AbstractSet

import structlog

from rasa.mantle.content.responses import ResponseButton
from rasa.mantle.content.static_buttons import (
    SET_MEMORY_PREFIX,
    SetMemoryPayloadError,
    is_set_memory_payload,
    parse_static_set_memory_payload,
)
from rasa.mantle.tools.buttons import Button

structlogger = structlog.get_logger()

_source_button_items: ContextVar[tuple[Button, ...] | None] = ContextVar(
    "source_button_items", default=None
)


@contextmanager
def capture_source_buttons() -> Iterator[None]:
    """Capture button values for one source-tool invocation."""
    token = _source_button_items.set(())
    try:
        yield
    finally:
        _source_button_items.reset(token)


def set_source_buttons(buttons: Sequence[Button]) -> None:
    """Replace buttons captured for the active source-tool invocation.

    Raises:
        RuntimeError: When called outside a source-tool invocation.
    """
    if _source_button_items.get() is None:
        raise RuntimeError(
            "ToolContext.set_buttons() is only available to a response button "
            "source tool."
        )
    normalized: list[Button] = []
    dropped = 0
    for entry in buttons:
        if isinstance(entry, Button):
            normalized.append(entry)
        else:
            dropped += 1
    if dropped:
        structlogger.debug(
            "mantle.dynamic_buttons.invalid_button_items_dropped",
            dropped_count=dropped,
        )
    _source_button_items.set(tuple(normalized))


def resolve_source_buttons(
    *,
    writable_memory_keys: AbstractSet[str] | None = None,
) -> tuple[ResponseButton, ...]:
    """Return valid captured buttons in the existing response-button shape.

    Raises:
        RuntimeError: When called outside a source-tool invocation.
    """
    items = _source_button_items.get()
    if items is None:
        raise RuntimeError("No response button source invocation is active.")
    return resolve_buttons(items, writable_memory_keys=writable_memory_keys)


def resolve_buttons(
    buttons: Sequence[object],
    *,
    writable_memory_keys: AbstractSet[str] | None = None,
) -> tuple[ResponseButton, ...]:
    """Resolve builder button values into delivery-ready response buttons.

    Entries that are not :class:`Button` values, and buttons that fail
    resolution, are dropped. A ``None`` writable-key set skips the memory-ref
    allowlist.

    Args:
        buttons: Builder button values, in order.
        writable_memory_keys: Fully-qualified memory keys a ``ref`` may write.
            ``None`` allows every ref that parses.

    Returns:
        Buttons that resolved, in the same order.
    """
    resolved: list[ResponseButton] = []
    skipped_count = 0
    for item in buttons:
        if not isinstance(item, Button):
            skipped_count += 1
            structlogger.debug(
                "mantle.dynamic_buttons.invalid_button_item",
                item_type=type(item).__name__,
            )
            continue
        button = resolve_source_button(
            item,
            writable_memory_keys=writable_memory_keys,
        )
        if button is None:
            skipped_count += 1
        else:
            resolved.append(button)

    if skipped_count:
        structlogger.debug(
            "mantle.dynamic_buttons.items_skipped",
            skipped_count=skipped_count,
        )
    return tuple(resolved)


def resolve_source_button(
    item: Button,
    *,
    writable_memory_keys: AbstractSet[str] | None,
) -> ResponseButton | None:
    """Resolve one builder button, or return ``None`` when it should be dropped.

    A button without ``ref`` uses ``value``, or ``title`` when ``value`` is
    omitted. That payload is dropped when it starts with ``set:``, because
    inbound handling would treat it as a memory write. A ``ref`` becomes a
    ``set:`` memory payload. Blank titles, blank payloads, and refs the skill
    may not write are dropped.

    Args:
        item: Builder button value.
        writable_memory_keys: Fully-qualified keys a memory ref may target.
            ``None`` does not apply that allowlist.

    Returns:
        The delivery button, or ``None`` when *item* is not usable.
    """
    if not item.title.strip():
        return None

    if item.ref is None:
        payload = item.title if item.value is None else item.value
        if not payload.strip() or is_set_memory_payload(payload):
            return None
        return ResponseButton(title=item.title, payload=payload)

    if not item.ref.strip():
        return None
    raw_value = "null" if item.value is None else item.value
    payload = f"{SET_MEMORY_PREFIX}{item.ref.strip()}={raw_value}"
    try:
        parsed = parse_static_set_memory_payload(payload)
    except SetMemoryPayloadError as exc:
        structlogger.warning(
            "mantle.dynamic_buttons.set_memory_payload_invalid",
            error=str(exc),
            recommendation=(
                "Use ref='session.<skill_id>.<entry_name>' with a value after '=' "
                "(Python None becomes 'null'); omit ref for plain-text taps."
            ),
        )
        structlogger.debug(
            "mantle.dynamic_buttons.set_memory_payload_invalid.details",
            title=item.title,
            ref=item.ref,
            value=item.value,
        )
        return None
    if (
        writable_memory_keys is not None
        and parsed.memory_key not in writable_memory_keys
    ):
        return None
    return ResponseButton(title=item.title, payload=payload)
